// Visual-only enhancements. Respect system and in-app reduced-motion settings.
const motionAllowed=()=>!matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.body.classList.contains('reduced');
const ambient=document.createElement('div');ambient.className='aero-ambient';ambient.setAttribute('aria-hidden','true');ambient.innerHTML='<div class="sun-halo"></div><div class="sky-cloud cloud-one"></div><div class="sky-cloud cloud-two"></div><div class="sky-cloud cloud-three"></div><div class="light-ribbon ribbon-one"></div><div class="light-ribbon ribbon-two"></div>'+Array.from({length:12},(_,i)=>`<i class="sky-spark" style="--spark-x:${(i*29+11)%100}%;--spark-y:${(i*17+9)%68}%;--spark-delay:${i*-.9}s"></i>`).join('');$('#desktop').prepend(ambient);
const visualOpen=openApp;openApp=function(id){const existed=opened.has(id),wasHidden=existed&&opened.get(id).hidden;visualOpen(id);let w=opened.get(id);if(w&&!w.dataset.visual){w.dataset.visual='1';const icon=document.createElement('span');icon.className='title-app-icon';icon.innerHTML=svg(id);w.querySelector('.titlebar').prepend(icon);const bar=w.querySelector('.titlebar');bar.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;w.classList.add('window-moving');const done=()=>w.classList.remove('window-moving');bar.addEventListener('pointerup',done,{once:true});bar.addEventListener('pointercancel',done,{once:true})});}if(wasHidden&&motionAllowed())w.animate([{opacity:0,transform:'translateY(45px) scale(.94)'},{opacity:1,transform:'none'}],{duration:380,easing:'cubic-bezier(.16,1,.3,1)'})};
document.addEventListener('pointerdown',e=>{const button=e.target.closest('button');if(!button||!motionAllowed())return;const rect=button.getBoundingClientRect();if(rect.width>500)return;const ripple=document.createElement('span');ripple.className='aero-click';ripple.style.left=e.clientX+'px';ripple.style.top=e.clientY+'px';document.body.append(ripple);setTimeout(()=>ripple.remove(),600)});
const visualTasks=tasks;tasks=function(){visualTasks();$('#tasks').querySelectorAll('[data-task]').forEach(button=>{const icon=document.createElement('span');icon.className='task-icon';icon.innerHTML=svg(button.dataset.task);button.prepend(icon)})};
const hint=document.createElement('div');hint.className='desktop-hint';hint.innerHTML='<span>✧</span> Tu espacio. A tu ritmo.<small>CLIC DERECHO PARA PERSONALIZAR</small>';$('#desktop').append(hint);
// A light desktop-only parallax; no motion over application windows.
let parallaxFrame=0;$('#desktop').addEventListener('pointermove',e=>{if(!motionAllowed()||e.pointerType==='touch'||e.target.closest('.window'))return;if(parallaxFrame)return;parallaxFrame=requestAnimationFrame(()=>{ambient.style.setProperty('--px',((e.clientX/innerWidth-.5)*12).toFixed(1)+'px');ambient.style.setProperty('--py',((e.clientY/innerHeight-.5)*8).toFixed(1)+'px');parallaxFrame=0})});$('#desktop').addEventListener('pointerleave',()=>{ambient.style.setProperty('--px','0px');ambient.style.setProperty('--py','0px')});
